SELECT p.id AS position_id, o.id, o.status, o.started_at, UNIX_TIMESTAMP(o.started_at) AS epoch_s, o.last_evidence_at, o.anchor_entry_price, o.best_entry_price, o.buy_count, o.watch_count, o.neutral_count, o.evidence_score, o.execution_source, o.decision_code, o.executed_at, o.latest_signal_id, LEFT(o.decision_explanation, 400) AS expl FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal e ON e.id = p.signal_id JOIN crypto_ai.execution_opportunity o ON o.symbol = p.symbol AND o.started_at BETWEEN DATE_SUB(e.generated_at, INTERVAL 3 HOUR) AND e.generated_at WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, o.started_at LIMIT 40